using Dapper;
using BelemRestaurantes.Web.Domain;
namespace BelemRestaurantes.Web.Data;
public sealed class RestaurantRepository(DbFactory db) {
 public async Task<IEnumerable<Restaurant>> Search(string? city,string? search,int limit=30) {await using var c=db.Open();return await c.QueryAsync<Restaurant>(@"select id,name,city,neighborhood,category,address,website,instagram,facebook,tiktok,youtube,photo_url as PhotoUrl,status,updated_at as UpdatedAt from public.restaurants where status='published' and (@city is null or lower(city)=lower(@city)) and (@search is null or name ilike '%'||@search||'%' or category ilike '%'||@search||'%') order by name limit @limit",new{city=string.IsNullOrWhiteSpace(city)?null:city,search=string.IsNullOrWhiteSpace(search)?null:search,limit=Math.Clamp(limit,1,100)});}
 public async Task<Restaurant?> Find(long id) {await using var c=db.Open();return await c.QueryFirstOrDefaultAsync<Restaurant>(@"select id,name,city,neighborhood,category,address,website,instagram,facebook,tiktok,youtube,photo_url as PhotoUrl,status,updated_at as UpdatedAt from public.restaurants where id=@id and status='published'",new{id});}
 public async Task AddSuggestion(RestaurantSuggestion s) {await using var c=db.Open();await c.ExecuteAsync(@"insert into public.suggestions(name,city,website,notes) values (@Name,@City,@Website,@Notes)",s);}
 public async Task<int> UpsertDiscovered(string name,string city,string? address,string placeId,string sourceUrl) {await using var c=db.Open();return await c.ExecuteAsync(@"insert into public.restaurants(name,city,address,status,google_place_id,created_source_url) values(@name,@city,@address,'pending',@placeId,@sourceUrl) on conflict (google_place_id) where google_place_id is not null do update set last_seen_at=now(),updated_at=now()",new{name,city,address,placeId,sourceUrl});}
 public async Task LogSync(string source,string city,string state,int count,string? error) {await using var c=db.Open();await c.ExecuteAsync(@"insert into public.sync_runs(source,city,state,item_count,error_message) values(@source,@city,@state,@count,@error)",new{source,city,state,count,error=error?.Length>500?error[..500]:error});}
}